class Car {
public:
    Car(string brand, string model, string color)
        : brand(brand), model(model), color(color) {}
private:
    string brand, model, color;
};

class CarBuilder {
public:
    CarBuilder& setBrand(string b) { brand = b; return *this; }
    CarBuilder& setModel(string m) { model = m; return *this; }
    CarBuilder& setColor(string c) { color = c; return *this; }
    Car build() const { return Car(brand, model, color); }
private:
    string brand, model, color;
};

Car car = CarBuilder().setBrand("Volvo").setColor("svart").build();

class MySingleton {
public:
    MySingleton(const MySingleton&) = delete;
    static MySingleton* getInstance() {
        if (instance == nullptr)
            instance = new MySingleton();
        return instance;
    }
private:
    MySingleton() {}
    static MySingleton* instance;
};

MySingleton* MySingleton::instance = nullptr;

